  const dp = {};
  dp['0,0'] = 0;
  for (let i = 1; i <= word1.length; i++) dp[i + ',0'] = i;
  for (let j = 1; j <= word2.length; j++) dp['0,' + j] = j;
  for (let i = 1; i <= word1.length; i++) {
    for (let j = 1; j <= word2.length; j++) {
      if (word1[i - 1] === word2[j - 1]) {
        dp[i + ',' + j] = dp[(i - 1) + ',' + (j - 1)];
      } else {
        dp[i + ',' + j] = 1 + Math.min(
          dp[i + ',' + (j - 1)],
          dp[(i - 1) + ',' + j],
          dp[(i - 1) + ',' + (j - 1)]
        );
      }
    }
  }
